-- ============================================================
-- CommuniShield — FULL synthetic sample data (generated file)
-- Generated by: npm run seed:generate   (server/scripts/seed/)
--
-- *** EVERY ROW BELOW IS FAKE TEST DATA ***
-- No real incident, person, address, reporter or conversation is
-- described by any text, name, coordinate or timestamp here. Every
-- coordinate is an interior point of the real Argao barangay
-- polygons, generated to evaluate the prototype only.
--
-- REUSES EXISTING ACCOUNTS (no passwords or login codes required):
--   poster1@communishield.local .. poster20@communishield.local
--   commenter1@communishield.local .. commenter15@communishield.local
-- Accounts, profiles, roles, credentials and credibility scores are untouched.
-- Admin metadata references one existing active admin/super-admin.
--
-- Data: 640 reports over 140 days, 6 planted hotspot clusters,
--        700 comments (525 usable analyses), 513 report sentiment rows
--        (452 usable), 513 credibility analyses, 350 likes,
--        150 images, 150 validations, 90 audit logs,
--        110 notifications, 400 credibility events,
--        8 announcements, 5 sentiment datasets.
--
-- Re-run safe: the file deletes its own rows first, matched by the
-- fixed UUID namespaces used below (a1b2c3d4-* reports, c0ffee00-*
-- comments, d5e7d47a-* datasets) and by the
-- 'Sample ' text markers, so live data is never touched. Everything
-- inserts inside ONE transaction. Dates are relative to now(), so
-- the data is always fresh whenever you paste it.
--
-- Schema tolerance: statements whose table a deployment may not have
-- (public.emergency_facilities, public.system_settings) run inside a
-- to_regclass() guard and are SKIPPED with a NOTICE when absent. The
-- legacy public.admin_posts table is never touched at all (superseded
-- by public.admin_announcement).
-- ============================================================

begin;

-- digest() comes from pgcrypto (enabled by default on Supabase). The local
-- search_path makes it resolvable whether pgcrypto lives in 'extensions'
-- (Supabase) or 'public' (self-hosted); every table reference is qualified.
create extension if not exists pgcrypto;
set local search_path = extensions, public;

-- Resolve real account IDs by email, never by hard-coded UUID. These temporary
-- lookup tables disappear at commit. Check BEFORE deleting/inserting anything.
create temporary table sample_seed_accounts on commit drop as
select u.id, expected.email, expected.kind, expected.slot,
       coalesce(nullif(p.user_name, ''), nullif(p.fullname, ''), expected.email) as display_name
from (values
  ('poster1@communishield.local', 'poster', 1),
  ('poster2@communishield.local', 'poster', 2),
  ('poster3@communishield.local', 'poster', 3),
  ('poster4@communishield.local', 'poster', 4),
  ('poster5@communishield.local', 'poster', 5),
  ('poster6@communishield.local', 'poster', 6),
  ('poster7@communishield.local', 'poster', 7),
  ('poster8@communishield.local', 'poster', 8),
  ('poster9@communishield.local', 'poster', 9),
  ('poster10@communishield.local', 'poster', 10),
  ('poster11@communishield.local', 'poster', 11),
  ('poster12@communishield.local', 'poster', 12),
  ('poster13@communishield.local', 'poster', 13),
  ('poster14@communishield.local', 'poster', 14),
  ('poster15@communishield.local', 'poster', 15),
  ('poster16@communishield.local', 'poster', 16),
  ('poster17@communishield.local', 'poster', 17),
  ('poster18@communishield.local', 'poster', 18),
  ('poster19@communishield.local', 'poster', 19),
  ('poster20@communishield.local', 'poster', 20),
  ('commenter1@communishield.local', 'commenter', 1),
  ('commenter2@communishield.local', 'commenter', 2),
  ('commenter3@communishield.local', 'commenter', 3),
  ('commenter4@communishield.local', 'commenter', 4),
  ('commenter5@communishield.local', 'commenter', 5),
  ('commenter6@communishield.local', 'commenter', 6),
  ('commenter7@communishield.local', 'commenter', 7),
  ('commenter8@communishield.local', 'commenter', 8),
  ('commenter9@communishield.local', 'commenter', 9),
  ('commenter10@communishield.local', 'commenter', 10),
  ('commenter11@communishield.local', 'commenter', 11),
  ('commenter12@communishield.local', 'commenter', 12),
  ('commenter13@communishield.local', 'commenter', 13),
  ('commenter14@communishield.local', 'commenter', 14),
  ('commenter15@communishield.local', 'commenter', 15)
) as expected(email, kind, slot)
left join auth.users u on lower(u.email) = expected.email
left join public.profiles p on p.id = u.id
where p.role = 'user' and p.status = 'Active';

create temporary table sample_seed_admin on commit drop as
select p.id from public.profiles p join auth.users u on u.id = p.id
where p.role in ('super_admin', 'admin') and p.status = 'Active'
order by (p.role = 'super_admin') desc, p.id
limit 1;

do $guard$
declare missing text;
begin
  select string_agg(expected.email, ', ' order by expected.email) into missing
  from (
    select 'poster' || n || '@communishield.local' as email from generate_series(1, 20) n
    union all
    select 'commenter' || n || '@communishield.local' as email from generate_series(1, 15) n
  ) expected
  where not exists (select 1 from pg_temp.sample_seed_accounts a where a.email = expected.email);
  if missing is not null then
    raise exception 'Sample seed stopped: missing or inactive user accounts/profiles: %', missing;
  end if;
  if not exists (select 1 from pg_temp.sample_seed_admin) then
    raise exception 'Sample seed stopped: an existing active admin or super-admin is required';
  end if;
end $guard$;

-- Compact session-local lookup keeps this paste-ready despite richer text.
create function pg_temp.sample_seed_user(text, integer) returns uuid
language sql stable strict as $stmt$
  select a.id from pg_temp.sample_seed_accounts a where a.kind = $1 and a.slot = $2
$stmt$;

-- 0) Remove any previous copy of this seed. Report rows are matched by
--    their fixed UUID prefix (their location starts with the barangay
--    name, so text matching would miss them); everything else by marker.
delete from public.sentiment_dataset_events
where dataset_id in (select id from public.sentiment_datasets where name like 'Sample dataset:%');

delete from public.sentiment_training_samples
where dataset_id in (select id from public.sentiment_datasets where name like 'Sample dataset:%');

delete from public.sentiment_datasets
where name like 'Sample dataset:%';

delete from public.report_validations
where report_id in (select id from public.reports where id::text like 'a1b2c3d4-%');

delete from public.audit_logs
where title like 'Sample log:%';

delete from public.notifications
where title like 'Sample notification:%';

delete from public.report_credibility_analysis
where report_id in (select id from public.reports where id::text like 'a1b2c3d4-%');

delete from public.sentiment_analysis
where subject_id in (select id from public.reports where id::text like 'a1b2c3d4-%')
   or subject_id in (select id from public.report_comments where id::text like 'c0ffee00-%');

delete from public.report_images
where report_id in (select id from public.reports where id::text like 'a1b2c3d4-%');

delete from public.report_likes
where report_id in (select id from public.reports where id::text like 'a1b2c3d4-%');

delete from public.report_comments
where report_id in (select id from public.reports where id::text like 'a1b2c3d4-%');

delete from public.credibility_events
where reason like 'Sample credibility event % (synthetic).'
  and report_id::text like 'a1b2c3d4-%';

delete from public.reports
where id::text like 'a1b2c3d4-%';

delete from public.admin_announcement
where details like 'Sample announcement:%';

do $guard$
begin
  if to_regclass('public.emergency_facilities') is not null then
    execute $stmt$
delete from public.emergency_facilities
where name like 'Sample %'
$stmt$;
  else
    raise notice 'CommuniShield seed: skipping public.emergency_facilities (relation not present)';
  end if;
end $guard$;

-- 1) Notification types only. Existing accounts/profiles are never modified.
insert into public.notification_types (name) values
  ('report_status'), ('nearby_incident'), ('admin_account'), ('report_submitted'),
  ('ai_validation'), ('report_approved'), ('system'), ('log')
on conflict (name) do nothing;

-- 2) Reports: 640 rows across 140 days. Timestamps are computed
--    relative to now(); status spans the whole lifecycle including Archived.
--    34 pins belong to the 6 planted clusters, 12 are scattered noise.
insert into public.reports (id, user_id, incident_type_id, location, latitude, longitude, poster_name, display_name_type, details, status, created_at, updated_at)
select v.id, v.user_id, t.id, v.location, v.latitude, v.longitude, a.display_name, 'Username', concat('Sample report: ', v.details), v.status,
       now() - make_interval(days => v.day_offset, mins => v.minute_offset),
       now() - make_interval(days => v.day_offset, mins => v.minute_offset)
from (values
  ('a1b2c3d4-0000-4000-8000-000000000000'::uuid, pg_temp.sample_seed_user('poster', 1), 'Theft', 'Lamacan, Purok 1 pin 1, Argao, Cebu', 9.880192::float8, 123.583668::float8, '[SIMULATED #1] Lamacan, duol sa gamay nga tindahan, ganihang buntag. Pagbalik nako gikan pagpalit, wala na akong bag sa lingkoranan. Wala ko kakita kinsay mikuha, basin nabalhin ra pud. Nabalaka ko kay naa didto akong mga gamit sa trabaho. Dili ni tinuod nga hitabo.', 'Pending Review', 1, 120),
  ('a1b2c3d4-0000-4000-8000-000100010001'::uuid, pg_temp.sample_seed_user('poster', 2), 'Flooding', 'Lamacan, Purok 1 pin 1, Argao, Cebu', 9.880192::float8, 123.583668::float8, '[SIMULATED #2] Lamacan, malapit sa maliit na tindahan, kaninang umaga. Tumaas ang tubig matapos ang ulan at natakpan ang gilid ng daan. Hindi ako tumawid dahil hindi kita ang kanal. Nahihirapan nang dumaan ang maliliit na motor. Hindi ito totoong pangyayari.', 'Under Verification', 2, 121),
  ('a1b2c3d4-0000-4000-8000-000200020002'::uuid, pg_temp.sample_seed_user('poster', 3), 'Lost Item', 'Lamacan, Purok 1 pin 2, Argao, Cebu', 9.880492::float8, 123.583968::float8, '[SIMULATED #3] Lamacan, malapit sa maliit na tindahan, kaninang umaga. Wala na ang pitaka ko pag-uwi. Baka nahulog sa dinaanan, wala akong nakitang kumuha. Kung may nakakita, pakibigay sa barangay at ako ang maglalarawan ng laman. Hindi ito totoong pangyayari.', 'Under Verification', 3, 122),
  ('a1b2c3d4-0000-4000-8000-000300030003'::uuid, pg_temp.sample_seed_user('poster', 4), 'Reckless Driving', 'Lamacan, Purok 1 pin 2, Argao, Cebu', 9.880492::float8, 123.583968::float8, '[SIMULATED #4] Lamacan, duol sa gamay nga tindahan, ganihang buntag. Naay motor nga kusog kaayo mopadagan duol sa mga naglakaw. Mikalit og preno ang tricycle. Wala ko kabasa sa plaka, dili ko gusto magtagna kinsay rider. Dili ni tinuod nga hitabo.', 'Under Verification', 4, 123),
  ('a1b2c3d4-0000-4000-8000-000400040004'::uuid, pg_temp.sample_seed_user('poster', 5), 'Suspicious Vehicle', 'Lamacan, Purok 1 pin 3, Argao, Cebu', 9.880192::float8, 123.584088::float8, '[SIMULATED #5] Lamacan, malapit sa maliit na tindahan, kaninang umaga. May van na matagal nakaparada sa gilid. Wala akong nakitang ilegal na ginawa. Nagtatanong lang kung may delivery rito para hindi tayo manghula. Hindi ito totoong pangyayari.', 'Pending Review', 5, 124),
  ('a1b2c3d4-0000-4000-8000-000500050005'::uuid, pg_temp.sample_seed_user('poster', 6), 'Public Disturbance', 'Lamacan, Purok 1 pin 3, Argao, Cebu', 9.880192::float8, 123.584088::float8, '[SIMULATED #6] Lamacan, near a small shop, earlier this morning. A loud argument outside could be heard from our house. I did not see a fight. The children were frightened, so I am asking if a tanod can check. This is not a real incident.', 'Under Verification', 6, 125),
  ('a1b2c3d4-0000-4000-8000-000600060006'::uuid, pg_temp.sample_seed_user('poster', 7), 'Streetlight Outage', 'Lamacan, Purok 1 pin 4, Argao, Cebu', 9.879892::float8, 123.583968::float8, '[SIMULATED #7] Lamacan, sa may waiting shed, ganihang buntag. Duha na ka gabii nga dili mosiga ang poste duol sa agianan. Ngitngit inig-uli gikan trabaho. Basin mapatan-aw, ilabi na kay naay mga estudyante nga moagi. Dili ni tinuod nga hitabo.', 'Under Verification', 7, 126),
  ('a1b2c3d4-0000-4000-8000-000700070007'::uuid, pg_temp.sample_seed_user('poster', 8), 'General Safety Concern', 'Lamacan, Purok 1 pin 4, Argao, Cebu', 9.879892::float8, 123.583968::float8, '[SIMULATED #8] Lamacan, sa may waiting shed, ganihang buntag. Naay liki nga tabon sa kanal nga matamakan sa naglakaw. Nakita nako nga molihok kon maagian. Wala koy nakita nga nasamdan, pero basin ma-check sa maintenance sa dili pa naay matumba. Dili ni tinuod nga hitabo.', 'Under Verification', 8, 127),
  ('a1b2c3d4-0000-4000-8000-000800080008'::uuid, pg_temp.sample_seed_user('poster', 9), 'Fire Incident', 'Lamacan, Purok 1 pin 5, Argao, Cebu', 9.880066::float8, 123.583668::float8, '[SIMULATED #9] Lamacan, by the waiting shed, earlier this morning. I saw dark smoke and flames from a small structure and moved away. I cannot confirm whether anyone was inside or what started the fire. This is not a real incident.', 'Pending Review', 9, 128),
  ('a1b2c3d4-0000-4000-8000-000900090009'::uuid, pg_temp.sample_seed_user('poster', 10), 'Online Scam / Suspicious Message', 'Lamacan, Purok 1 pin 5, Argao, Cebu', 9.880066::float8, 123.583668::float8, '[SIMULATED #10] Lamacan, sa may waiting shed, ganihang buntag. Nakadawat kog text nga kuno ma-lock akong account ug kinahanglan pindoton ang link. Wala nako giablihan. Wala koy na-transfer nga kwarta. Basin makatabang nga pahimangno sa uban. Dili ni tinuod nga hitabo.', 'Under Verification', 10, 129),
  ('a1b2c3d4-0000-4000-8000-000a000a000a'::uuid, pg_temp.sample_seed_user('poster', 11), 'Vehicular Accident', 'Lamacan, Purok 1 pin 6, Argao, Cebu', 9.880102::float8, 123.583578::float8, '[SIMULATED #11] Lamacan, sa may waiting shed, kagahapong hapon. Nakita nako ang duha ka motor nga nagbangga. Ang usa ka rider naglingkod sa kilid ug nagreklamo sa tiil. Wala ko kahibalo sa hinungdan, ug dili ko makasulti unsa kabug-at ang iyang samad. Dili ni tinuod nga hitabo.', 'Under Verification', 11, 130),
  ('a1b2c3d4-0000-4000-8000-000b000b000b'::uuid, pg_temp.sample_seed_user('poster', 12), 'Suspicious Person', 'Lamacan, Purok 1 pin 6, Argao, Cebu', 9.880102::float8, 123.583578::float8, '[SIMULATED #12] Lamacan, sa may waiting shed, kagahapong hapon. Naay wala nako mailhi nga nangutana kon kinsa ang naa sa balay. Wala siyay hulga ug milakaw ra. Basin delivery ra, pero wala mi gipaabot. Observation lang ni, dili akusasyon. Dili ni tinuod nga hitabo.', 'Under Verification', 12, 131),
  ('a1b2c3d4-0000-4000-8000-000c000c000c'::uuid, pg_temp.sample_seed_user('poster', 13), 'Theft', 'Lamacan, Purok 1 pin 7, Argao, Cebu', 9.880192::float8, 123.583248::float8, '[SIMULATED #13] Lamacan, sa may waiting shed, kagahapong hapon. Pagbalik nako gikan pagpalit, wala na akong bag sa lingkoranan. Wala ko kakita kinsay mikuha, basin nabalhin ra pud. Nabalaka ko kay naa didto akong mga gamit sa trabaho. Dili ni tinuod nga hitabo.', 'Pending Review', 13, 132),
