  ('a1b2c3d4-0000-4000-8000-01b901b901b9'::uuid, pg_temp.sample_seed_user('poster', 2), 'Reckless Driving', 'Talo-ot, Sample street 10, Argao, Cebu', 9.953423::float8, 123.612153::float8, '[SIMULATED #442] Talo-ot, duol sa agianan padulong sa mga balay, ganihang buntag. Naay motor nga kusog kaayo mopadagan duol sa mga naglakaw. Mikalit og preno ang tricycle. Wala ko kabasa sa plaka, dili ko gusto magtagna kinsay rider. Dili ni tinuod nga hitabo.', 'Under Verification', 135, 561),
