  ('a1b2c3d4-0000-4000-8000-027502750275'::uuid, pg_temp.sample_seed_user('poster', 10), 'General Safety Concern', 'Sumaguan, Sample street 6, Argao, Cebu', 9.962080::float8, 123.596034::float8, '[SIMULATED #630] Sumaguan, sa gilid ng kurbada, kahapon ng hapon. May bitak ang takip ng kanal sa dinaraanan. Gumagalaw kapag natatapakan. Wala akong nakitang nasaktan, pero sana matingnan ng maintenance bago may madapa. Hindi ito totoong pangyayari.', 'Under Verification', 38, 149),
  ('a1b2c3d4-0000-4000-8000-027602760276'::uuid, pg_temp.sample_seed_user('poster', 11), 'Streetlight Outage', 'Mompeller, Sample street 7, Argao, Cebu', 9.978921::float8, 123.526870::float8, '[SIMULATED #631] Mompeller, sa gilid ng kurbada, kahapon ng hapon. Dalawang gabi nang hindi umiilaw ang poste malapit sa daanan. Madilim pauwi galing trabaho. Sana matingnan dahil may mga estudyanteng dumadaan. Update: umiilaw na nang dumaan ako kagabi. Salamat sa nag-follow up.', 'Resolved', 56, 150),
  ('a1b2c3d4-0000-4000-8000-027702770277'::uuid, pg_temp.sample_seed_user('poster', 12), 'Public Disturbance', 'Linut-od, Sample street 8, Argao, Cebu', 9.882641::float8, 123.478362::float8, '[SIMULATED #632] Linut-od, sa kilid sa kurbada, kagahapong hapon. Naay kusog nga panaglalis sa gawas. Nadungog sa among balay pero wala ko kakita og sinumbagay. Nabalaka ang mga bata, basin pwede ma-check sa tanod. Update: nahunong ang lalis ug nilakaw na sila. Hilom na balik.', 'Resolved', 63, 151),
  ('a1b2c3d4-0000-4000-8000-027802780278'::uuid, pg_temp.sample_seed_user('poster', 13), 'Suspicious Vehicle', 'Talaytay, Sample street 9, Argao, Cebu', 9.894372::float8, 123.596405::float8, '[SIMULATED #633] Talaytay, sa gilid ng kurbada, kahapon ng hapon. May van na matagal nakaparada sa gilid. Wala akong nakitang ilegal na ginawa. Nagtatanong lang kung may delivery rito para hindi tayo manghula. Review update: hindi ito nakumpirma. Huwag ibahagi bilang totoong pangyayari.', 'Rejected', 70, 152),
  ('a1b2c3d4-0000-4000-8000-027902790279'::uuid, pg_temp.sample_seed_user('poster', 14), 'Reckless Driving', 'Talo-ot, Sample street 10, Argao, Cebu', 9.953423::float8, 123.612153::float8, '[SIMULATED #634] Talo-ot, beside the bend, yesterday afternoon. A motorcycle passed very fast close to pedestrians and a tricycle braked suddenly. I could not read the plate and will not guess who was riding. Review update: this was not confirmed. Do not share it as a real event.', 'Marked Fake', 77, 153),
  ('a1b2c3d4-0000-4000-8000-027a027a027a'::uuid, pg_temp.sample_seed_user('poster', 15), 'Lost Item', 'Gutlang, Sample street 11, Argao, Cebu', 9.976688::float8, 123.562828::float8, '[SIMULATED #635] Gutlang, sa kilid sa kurbada, kagahapong hapon. Wala na akong pitaka pag-abot sa balay. Basin natagak sa akong gilakwan, wala ko kakita nga naay mikuha. Kon naay nakakita, i-turn over lang sa barangay ug ako mismo mo-describe sa sulod. Dili ni tinuod nga hitabo.', 'Under Verification', 84, 154),
  ('a1b2c3d4-0000-4000-8000-027b027b027b'::uuid, pg_temp.sample_seed_user('poster', 16), 'Flooding', 'Jampang, Sample street 12, Argao, Cebu', 9.903223::float8, 123.575248::float8, '[SIMULATED #636] Jampang, beside the bend, yesterday afternoon. Water rose after the rain and covered the road edge. I did not cross because the drainage channel was hidden. Small motorcycles were having difficulty passing. This is not a real incident.', 'Pending Review', 102, 155),
  ('a1b2c3d4-0000-4000-8000-027c027c027c'::uuid, pg_temp.sample_seed_user('poster', 17), 'Theft', 'Poblacion, Sample street 1, Argao, Cebu', 9.876321::float8, 123.603517::float8, '[SIMULATED #637] Poblacion, near the path leading to the houses, yesterday afternoon. My bag was missing when I returned from the shop. I did not see anyone take it, so I cannot say whether it was stolen or moved. My work things were inside and I am worried. Update: staff found the bag on another seat. The search has ended.', 'Resolved', 109, 156),
  ('a1b2c3d4-0000-4000-8000-027d027d027d'::uuid, pg_temp.sample_seed_user('poster', 18), 'Suspicious Person', 'Langtad, Sample street 2, Argao, Cebu', 9.888126::float8, 123.606583::float8, '[SIMULATED #638] Langtad, duol sa agianan padulong sa mga balay, kagabii. Naay wala nako mailhi nga nangutana kon kinsa ang naa sa balay. Wala siyay hulga ug milakaw ra. Basin delivery ra, pero wala mi gipaabot. Observation lang ni, dili akusasyon. Dili ni tinuod nga hitabo.', 'Archived', 116, 157),
  ('a1b2c3d4-0000-4000-8000-027e027e027e'::uuid, pg_temp.sample_seed_user('poster', 19), 'Vehicular Accident', 'Canbanua, Sample street 3, Argao, Cebu', 9.885929::float8, 123.586229::float8, '[SIMULATED #639] Canbanua, duol sa agianan padulong sa mga balay, kagabii. Nakita nako ang duha ka motor nga nagbangga. Ang usa ka rider naglingkod sa kilid ug nagreklamo sa tiil. Wala ko kahibalo sa hinungdan, ug dili ko makasulti unsa kabug-at ang iyang samad. Dili ni tinuod nga hitabo.', 'Pending Review', 123, 158),
  ('a1b2c3d4-0000-4000-8000-027f027f027f'::uuid, pg_temp.sample_seed_user('poster', 20), 'Online Scam / Suspicious Message', 'Casay, Sample street 4, Argao, Cebu', 9.839715::float8, 123.557829::float8, '[SIMULATED #640] Casay, duol sa agianan padulong sa mga balay, kagabii. Nakadawat kog text nga kuno ma-lock akong account ug kinahanglan pindoton ang link. Wala nako giablihan. Wala koy na-transfer nga kwarta. Basin makatabang nga pahimangno sa uban. Dili ni tinuod nga hitabo.', 'Under Verification', 130, 159)
) as v(id, user_id, type_name, location, latitude, longitude, details, status, day_offset, minute_offset)
left join public.incident_types t on t.name = v.type_name
join pg_temp.sample_seed_accounts a on a.id = v.user_id and a.kind = 'poster'
on conflict (id) do nothing;

-- 3) Credibility analyses (severity feeds the Risk Prediction tiles).
insert into public.report_credibility_analysis (report_id, ai_score, severity, credibility_level, credibility_review, ai_model_version, analysis_duration_ms, analyzed_at)
select v.report_id, v.ai_score, v.severity, v.credibility_level,
       concat('Sample AI review: [SIMULATED] ', v.type_name, '. Unverified text. Scenario severity is not emotional tone.'),
       'CommuniShield-AI v1.0', 120 + (v.day_offset * 13) % 400,
       now() - make_interval(days => v.day_offset, mins => 90)
