-- 5) Comments plus their own sentiment rows.
insert into public.report_comments (id, report_id, user_id, content, created_at)
select v.id, v.report_id, v.user_id, concat('Sample comment: [SIMULATED] ', v.content), now() - make_interval(days => v.day_offset, mins => v.minute_offset)
from (values
  ('c0ffee00-0000-4000-8000-000100010001'::uuid, 'a1b2c3d4-0000-4000-8000-000000000000'::uuid, pg_temp.sample_seed_user('commenter', 1), 'Nakapangutana na ka sa tindahan basin naa sa lost-and-found?', 1, 117),
  ('c0ffee00-0000-4000-8000-000200020002'::uuid, 'a1b2c3d4-0000-4000-8000-000000000000'::uuid, pg_temp.sample_seed_user('commenter', 2), 'Ayaw lang sa ta pagngalan og tawo nga walay ebidensya. Itago ang resibo kon naa.', 1, 110),
  ('c0ffee00-0000-4000-8000-000300030003'::uuid, 'a1b2c3d4-0000-4000-8000-000000000000'::uuid, pg_temp.sample_seed_user('commenter', 3), 'Nakaagi ko sa Lamacan, pero wala nako makita ang tibuok bahin sa nawalang bag. Dili nako ma-confirm ang tanan.', 1, 103),
  ('c0ffee00-0000-4000-8000-000400040004'::uuid, 'a1b2c3d4-0000-4000-8000-000000000000'::uuid, pg_temp.sample_seed_user('commenter', 4), 'Update sa nawalang bag: nangutana na mi sa barangay. Wala pa mi nadawat nga kumpirmadong resulta.', 1, 96),
  ('c0ffee00-0000-4000-8000-000500050005'::uuid, 'a1b2c3d4-0000-4000-8000-000000000000'::uuid, pg_temp.sample_seed_user('commenter', 5), 'Nabalaka ko aning nawalang bag. Unta ma-check dayon, pero ayaw sa ta pagpakalat og wala makumpirma.', 1, 89),
  ('c0ffee00-0000-4000-8000-000600060006'::uuid, 'a1b2c3d4-0000-4000-8000-000000000000'::uuid, pg_temp.sample_seed_user('commenter', 6), 'Salamat sa klarong update. Mas maayo gyud nga naay follow-up.', 1, 82),
  ('c0ffee00-0000-4000-8000-000700070007'::uuid, 'a1b2c3d4-0000-4000-8000-000000000000'::uuid, pg_temp.sample_seed_user('commenter', 7), 'Unsang orasa nimo na-check ang nawalang bag? Basin lahi na ang kahimtang karon.', 1, 75),
  ('c0ffee00-0000-4000-8000-000800080008'::uuid, 'a1b2c3d4-0000-4000-8000-000000000000'::uuid, pg_temp.sample_seed_user('commenter', 8), 'Nag-message ako sa pamilya na tingnan muna ang update bago dumaan.', 1, 68),
  ('c0ffee00-0000-4000-8000-000900090009'::uuid, 'a1b2c3d4-0000-4000-8000-000000000000'::uuid, pg_temp.sample_seed_user('commenter', 9), 'Linawin ko lang: sariling obserbasyon ang ibinahagi ko, hindi opisyal na findings. Sandali lang akong dumaan at hindi ako nanatili roon. Maaaring may detalyeng hindi ko nakita, kaya hindi ko makumpirma ang buong report.', 1, 61),
  ('c0ffee00-0000-4000-8000-000a000a000a'::uuid, 'a1b2c3d4-0000-4000-8000-000000000000'::uuid, pg_temp.sample_seed_user('commenter', 10), 'Please do not forward undated screenshots. They may refer to an older update.', 1, 54),
  ('c0ffee00-0000-4000-8000-000b000b000b'::uuid, 'a1b2c3d4-0000-4000-8000-000000000000'::uuid, pg_temp.sample_seed_user('commenter', 11), 'Naa pa bay bag-ong balita sa Lamacan? Wala ko sa lugar karon.', 1, 47),
  ('c0ffee00-0000-4000-8000-000c000c000c'::uuid, 'a1b2c3d4-0000-4000-8000-000000000000'::uuid, pg_temp.sample_seed_user('commenter', 12), 'Salamat sa paglilinaw. Mas malinaw na ngayon kaysa sa una kong narinig.', 1, 40),
  ('c0ffee00-0000-4000-8000-000d000d000d'::uuid, 'a1b2c3d4-0000-4000-8000-002500250025'::uuid, pg_temp.sample_seed_user('commenter', 13), 'Makaya pa sa multicab o mas maayo mangita og laing agianan?', 16, 153),
  ('c0ffee00-0000-4000-8000-000e000e000e'::uuid, 'a1b2c3d4-0000-4000-8000-002500250025'::uuid, pg_temp.sample_seed_user('commenter', 14), 'Dili ta makasiguro sa giladmon pinaagi sa litrato. Ayaw pugsa og tabok.', 16, 146),
  ('c0ffee00-0000-4000-8000-000f000f000f'::uuid, 'a1b2c3d4-0000-4000-8000-004a004a004a'::uuid, pg_temp.sample_seed_user('commenter', 15), 'Naa nay nitawag og tabang para sa rider?', 112, 189),
  ('c0ffee00-0000-4000-8000-001000100010'::uuid, 'a1b2c3d4-0000-4000-8000-004a004a004a'::uuid, pg_temp.sample_seed_user('commenter', 1), 'Ayaw ibalhin ang nasamdan gawas kon naay diha-diha nga peligro. Hatagi og agianan ang responders.', 112, 182),
  ('c0ffee00-0000-4000-8000-001100110011'::uuid, 'a1b2c3d4-0000-4000-8000-004a004a004a'::uuid, pg_temp.sample_seed_user('commenter', 2), 'Nakaagi ko sa Canbanua, pero wala nako makita ang tibuok bahin sa bangga sa motor. Dili nako ma-confirm ang tanan.', 112, 175),
  ('c0ffee00-0000-4000-8000-001200120012'::uuid, 'a1b2c3d4-0000-4000-8000-006f006f006f'::uuid, pg_temp.sample_seed_user('commenter', 3), 'Naa pud moy nadawat nga pareho nga text? Ayaw lang i-share ang link.', 39, 225),
  ('c0ffee00-0000-4000-8000-001300130013'::uuid, 'a1b2c3d4-0000-4000-8000-006f006f006f'::uuid, pg_temp.sample_seed_user('commenter', 4), 'Ayaw ihatag ang OTP o password. Gamita ang opisyal nga app sa pag-check.', 39, 218),
  ('c0ffee00-0000-4000-8000-001400140014'::uuid, 'a1b2c3d4-0000-4000-8000-006f006f006f'::uuid, pg_temp.sample_seed_user('commenter', 5), 'Nakaagi ko sa Casay, pero wala nako makita ang tibuok bahin sa kadudahang mensahe. Dili nako ma-confirm ang tanan.', 39, 211),
  ('c0ffee00-0000-4000-8000-001500150015'::uuid, 'a1b2c3d4-0000-4000-8000-006f006f006f'::uuid, pg_temp.sample_seed_user('commenter', 6), 'Update sa kadudahang mensahe: nangutana na mi sa barangay. Wala pa mi nadawat nga kumpirmadong resulta.', 39, 204),
  ('c0ffee00-0000-4000-8000-001600160016'::uuid, 'a1b2c3d4-0000-4000-8000-009400940094'::uuid, pg_temp.sample_seed_user('commenter', 7), 'Has the fire service been contacted, and are you in a safe place?', 95, 261),
  ('c0ffee00-0000-4000-8000-001700170017'::uuid, 'a1b2c3d4-0000-4000-8000-009400940094'::uuid, pg_temp.sample_seed_user('commenter', 8), 'Ayaw sulod balik para sa gamit. Palayo ug ayaw babagan ang agianan sa bombero.', 95, 254),
  ('c0ffee00-0000-4000-8000-001800180018'::uuid, 'a1b2c3d4-0000-4000-8000-009400940094'::uuid, pg_temp.sample_seed_user('commenter', 9), 'Nakaagi ko sa Colawin, pero wala nako makita ang tibuok bahin sa aso ug siga. Dili nako ma-confirm ang tanan.', 95, 247),
  ('c0ffee00-0000-4000-8000-001900190019'::uuid, 'a1b2c3d4-0000-4000-8000-009400940094'::uuid, pg_temp.sample_seed_user('commenter', 10), 'Update sa aso ug siga: nangutana na mi sa barangay. Wala pa mi nadawat nga kumpirmadong resulta.', 95, 240),
  ('c0ffee00-0000-4000-8000-001a001a001a'::uuid, 'a1b2c3d4-0000-4000-8000-009400940094'::uuid, pg_temp.sample_seed_user('commenter', 11), 'Nabalaka ko aning aso ug siga. Unta ma-check dayon, pero ayaw sa ta pagpakalat og wala makumpirma.', 95, 233),
  ('c0ffee00-0000-4000-8000-001b001b001b'::uuid, 'a1b2c3d4-0000-4000-8000-00b900b900b9'::uuid, pg_temp.sample_seed_user('commenter', 12), 'Is it beside the pedestrian path?', 22, 297),
  ('c0ffee00-0000-4000-8000-001c001c001c'::uuid, 'a1b2c3d4-0000-4000-8000-00de00de00de'::uuid, pg_temp.sample_seed_user('commenter', 13), 'Iyong poste po ba sa tabi ng maliit na tindahan?', 78, 333),
  ('c0ffee00-0000-4000-8000-001d001d001d'::uuid, 'a1b2c3d4-0000-4000-8000-00de00de00de'::uuid, pg_temp.sample_seed_user('commenter', 14), 'Do not touch the wiring. Give maintenance the pole number if it can be read safely.', 78, 326),
