  ('c0ffee00-0000-4000-8000-002700270027'::uuid, 'a1b2c3d4-0000-4000-8000-014d014d014d'::uuid, pg_temp.sample_seed_user('commenter', 9), 'Dumaan ako sa Talo-ot pero hindi ko nakita ang buong pangyayari sa mabilis na pagpapatakbo. Hindi ko makumpirma ang lahat.', 117, 427),
  ('c0ffee00-0000-4000-8000-002800280028'::uuid, 'a1b2c3d4-0000-4000-8000-014d014d014d'::uuid, pg_temp.sample_seed_user('commenter', 10), 'Update: tapos na ang pag-check sa daan. Walang kumpirmadong pagkakakilanlan ng rider.', 117, 420),
